const chapters=[["01 · SẢNH VĂN PHÒNG", "8:30 sáng. Văn phòng hôm nay có gì đó khác: trên bàn là một tấm bản đồ cùng lời nhắn “Hôm nay, deadline duy nhất là vui vẻ.” Cùng đi một vòng để tìm sáu dấu ấn của những người đồng nghiệp tuyệt vời nhé.", "Ghé Góc cà phê →"], ["02 · GÓC CÀ PHÊ · MỘT KHỞI ĐẦU DỄ CHỊU", "Máy pha cà phê đã sẵn sàng. Có những buổi sáng, một câu “Uống gì không, mình lấy giúp?” khiến ngày mới dễ chịu hẳn. Dấu ấn đầu tiên: sự quan tâm từ những việc rất nhỏ.", "Đến Vườn ý tưởng →"], ["03 · VƯỜN Ý TƯỞNG · MỖI GÓC NHÌN ĐỀU CÓ GIÁ TRỊ", "Một cuộc họp đang hơi bí ý tưởng. Ai đó lên tiếng: “Hay mình thử cách khác?” Và cả nhóm tìm được hướng đi mới. Cảm ơn những người luôn dám đề xuất, đặt câu hỏi và biến điều chưa rõ thành điều có thể làm.", "Qua Cầu đồng đội →"], ["04 · CẦU ĐỒNG ĐỘI · CÙNG NHAU THÌ NHẸ HƠN", "Một đầu cầu là task còn dang dở, đầu kia là ngày bàn giao. Chiếc cầu được dựng bằng những câu “Để mình xem cùng”, “Mình hỗ trợ phần này nhé”. Làm đồng nghiệp không chỉ là ngồi gần, mà còn là sẵn sàng giúp nhau tiến lên.", "Ghé Trạm nạp năng lượng →"], ["05 · TRẠM NẠP NĂNG LƯỢNG · NGHỈ MỘT CHÚT NHÉ", "Bạn đã đi được một quãng dài. Ở đây không có thông báo họp: chỉ có cây xanh, ghế nghỉ và một lời nhắc uống nước. Chúc các bạn có thời gian cho bản thân, cho sở thích và cho những niềm vui ngoài công việc.", "Đến Bưu điện lời cảm ơn →"], ["06 · BƯU ĐIỆN LỜI CẢM ƠN · NHỮNG ĐIỀU ÍT KHI NÓI", "Trong chiếc hòm thư có những mẩu giấy: “Cảm ơn vì đã giải thích lại”, “Cảm ơn vì góp ý thẳng thắn”, “Cảm ơn vì luôn giữ lời”. Có những đóng góp âm thầm nhưng đội ngũ luôn cần và trân trọng.", "Lên Sân thượng 20/10 →"], ["07 · SÂN THƯỢNG 20/10 · HÔM NAY LÀ NGÀY CỦA CÁC BẠN", "Bản đồ đã đủ sáu dấu ấn. Trên sân thượng, một buổi gặp mặt nhỏ đang chờ: có bánh, hoa và những lời chúc từ đồng đội. Cảm ơn các bạn vì chuyên môn, sự tận tâm và cá tính riêng làm nên một đội ngũ nhiều màu sắc.", "Mở thiệp từ đồng đội ✦"]];
