const mats={grass:mat(0x789d83),rock:mat(0x536f70),edge:mat(0x3a555e),wood:mat(0xa67a56),gold:mat(0xffcc78,.4),pink:mat(0xe7a6a0),green:mat(0x456e62),cream:mat(0xf5e5bd),dark:mat(0x304c54)};
function mat(c,r=.85){return new T.MeshStandardMaterial({color:c,roughness:r});}
function mesh(g,m,p,parent=scene){const o=new T.Mesh(g,m);o.position.set(...p);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}
function box(x,y,z,m,p,parent){return mesh(new T.BoxGeometry(x,y,z),m,p,parent);}
function cylinder(r1,r2,h,m,p,parent,n=8){return mesh(new T.CylinderGeometry(r1,r2,h,n),m,p,parent);}
function sphere(r,m,p,parent){return mesh(new T.IcosahedronGeometry(r,1),m,p,parent);}
function textSprite(txt,size=1.5){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#fff0c9';ctx.font='600 80px sans-serif';ctx.textAlign='center';ctx.fillText(txt,512,150);const s=new T.Sprite(new T.SpriteMaterial({map:new T.CanvasTexture(c),depthTest:false,transparent:true}));s.scale.set(size*4,size,1);return s;}
const islands=[],clickables=[],gifts=[];
stops.forEach((p,i)=>{const g=new T.Group();g.position.copy(p);scene.add(g);islands.push(g);cylinder(2.65,2.35,.5,mats.grass,[0,-.25,0],g,10);cylinder(2.3,.4,2.5,mats.rock,[0,-1.7,0],g,7);cylinder(1.4,.2,1.6,mats.edge,[.35,-3,0],g,5);const pad=cylinder(1.1,1.1,.05,mats.cream,[0,.04,0],g,32);pad.userData.stop=i;clickables.push(pad);for(let j=0;j<7;j++){const a=j/7*Math.PI*2;const rock=sphere(.15,mats.cream,[Math.cos(a)*2.15,.1,Math.sin(a)*2.15],g);rock.scale.y=.5;}const label=textSprite(names[i].toUpperCase(),.52);label.position.set(0,3.5,0);g.add(label);});
function tree(g,x,z,s=1){cylinder(.09,.14,1.2*s,mats.wood,[x,.6*s,z],g);cylinder(0,.6*s,1.3*s,mats.green,[x,1.45*s,z],g,6);cylinder(0,.45*s,1*s,mats.grass,[x,2*s,z],g,6);}
tree(islands[0],-1.5,-.8);tree(islands[0],1.2,-1.2,.7);tree(islands[2],-1.4,-1,.9);tree(islands[2],1.5,.6,.7);tree(islands[3],-1.5,.7,.6);tree(islands[6],1.3,-1,.8);
// A tiny office departure dock and paper boat.
for(let i=0;i<5;i++)box(.34,.12,1.6,mats.wood,[-.7+i*.35,.1,2.1],islands[0]);const boat=mesh(new T.ConeGeometry(.6,.5,3),mats.cream,[0,.4,2.4],islands[0]);boat.rotation.z=Math.PI;box(.04,1,.04,mats.wood,[0,.9,2.4],islands[0]);const sail=mesh(new T.ConeGeometry(.4,.65,3),mats.pink,[.15,1.1,2.4],islands[0]);sail.rotation.y=Math.PI/2;
// Idea garden: flowers around a little worktable.
box(1.1,.12,.65,mats.wood,[0,.7,-.8],islands[2]);for(const x of [-.4,.4])box(.08,.7,.08,mats.wood,[x,.35,-.8],islands[2]);box(.5,.03,.35,mats.cream,[0,.79,-.8],islands[2]);for(let i=0;i<13;i++){const a=i*2.4,r=1.2+(i%3)*.3,x=Math.cos(a)*r,z=Math.sin(a)*r;cylinder(.025,.025,.4,mats.green,[x,.2,z],islands[2]);for(let j=0;j<5;j++){const b=j/5*6.28;sphere(.12,mats.pink,[x+Math.cos(b)*.12,.45,z+Math.sin(b)*.12],islands[2]);}sphere(.08,mats.gold,[x,.49,z],islands[2]);}
// Lighthouse with a rotating warm beacon.
cylinder(.5,.7,2.3,mats.cream,[.35,1.15,-.7],islands[3]);cylinder(.52,.58,.25,mats.pink,[.35,1.7,-.7],islands[3]);cylinder(.65,.65,.15,mats.dark,[.35,2.35,-.7],islands[3]);cylinder(.38,.38,.55,mats.gold,[.35,2.7,-.7],islands[3]);cylinder(0,.65,.45,mats.dark,[.35,3.15,-.7],islands[3]);const beacon=new T.PointLight(0xffcc77,6,12);beacon.position.copy(stops[3]).add(new T.Vector3(.35,2.8,-.7));scene.add(beacon);
// Final plaza, gift and celebration arch.
for(const x of [-1.2,1.2])cylinder(.07,.07,2.3,mats.gold,[x,1.15,-.5],islands[6]);const arch=mesh(new T.TorusGeometry(1.2,.07,8,32,Math.PI),mats.gold,[0,2.3,-.5],islands[6]);const title=textSprite('20 / 10',.5);title.position.set(0,2.6,-.45);islands[6].add(title);box(.9,.7,.9,mats.pink,[0,.4,0],islands[6]);box(1,.15,1,mats.cream,[0,.82,0],islands[6]);box(.13,.8,.93,mats.gold,[0,.43,0],islands[6]);box(.93,.8,.13,mats.gold,[0,.43,0],islands[6]);for(const x of [-.2,.2]){const b=mesh(new T.TorusGeometry(.21,.045,7,24),mats.gold,[x,1,.0],islands[6]);b.rotation.y=.4;b.scale.y=.65;}

// Coffee counter, cups and striped canopy.
const cafe=islands[1];box(2,.9,.8,mats.wood,[0,.45,-.8],cafe);box(2.2,.12,1,mats.cream,[0,.95,-.8],cafe);box(.6,.65,.5,mats.dark,[.4,1.3,-.8],cafe);for(let i=0;i<3;i++){cylinder(.12,.1,.22,mats.cream,[-.65+i*.33,1.12,-.55],cafe,12);}for(const x of [-1.2,1.2])cylinder(.045,.045,2.4,mats.gold,[x,1.2,-1.2],cafe);for(let i=0;i<6;i++)box(.44,.12,1.3,i%2?mats.pink:mats.cream,[-1.1+i*.44,2.4,-.9],cafe);tree(cafe,1.65,.7,.6);
